            { "active.bomb.desc", new[] { "Через секунду взрывается. Ломает трещины в стенах. Заряд: {0} комната", "Explodes a second later. Breaks cracks in walls. Charge: {0} room", "一秒后爆炸，能炸开墙上的裂缝。充能：{0}个房间", "Explota un segundo después. Rompe grietas. Carga: {0} sala" } },
            { "active.freeze.name", new[] { "Ледяной кристалл", "Ice Crystal", "冰晶", "Cristal de hielo" } },
            { "active.freeze.desc", new[] { "Замораживает всех врагов на 3 с. Заряд: {0} комнаты", "Freezes every enemy for 3 s. Charge: {0} rooms", "冻结所有敌人3秒。充能：{0}个房间", "Congela a todos los enemigos 3 s. Carga: {0} salas" } },
            { "active.teleport.name", new[] { "Свиток телепорта", "Teleport Scroll", "传送卷轴", "Pergamino de teleporte" } },
            { "active.teleport.desc", new[] { "Переносит туда, куда указывает прицел. Заряд: {0} комнаты", "Takes you where you aim. Charge: {0} rooms", "传送到准星位置。充能：{0}个房间", "Te lleva a donde apuntas. Carga: {0} salas" } },
