            { "active.barrier.name", new[] { "Барьер", "Barrier", "屏障", "Barrera" } },
            { "active.barrier.desc", new[] { "3 с неуязвимости, отталкивает врагов и стирает снаряды рядом. Заряд: {0} комнаты", "3 s of invulnerability, pushes enemies and erases shots nearby. Charge: {0} rooms", "3秒无敌，击退敌人并消除附近子弹。充能：{0}个房间", "3 s de invulnerabilidad, empuja enemigos y borra disparos. Carga: {0} salas" } },
            { "active.storm.name", new[] { "Гнев Системы", "System's Wrath", "系统之怒", "Ira del Sistema" } },
            { "active.storm.desc", new[] { "Шесть молний бьют по врагам. Заряд: {0} комнаты", "Six lightning bolts strike the enemies. Charge: {0} rooms", "六道闪电劈向敌人。充能：{0}个房间", "Seis rayos golpean a los enemigos. Carga: {0} salas" } },
