            { "boss.ogre", new[] { "Огр", "The Ogre", "食人魔", "El ogro" } },
            { "boss.ogre.rule", new[] { "Разбегается и бьёт оземь. Уходи с линии удара", "Charges and slams the ground. Get out of the way", "冲锋并重击地面。避开冲撞路线", "Embiste y golpea el suelo. Apártate de su camino" } },
            { "boss.zombie", new[] { "Гнилой великан", "The Rotting Giant", "腐烂巨人", "El gigante podrido" } },
            { "boss.zombie.rule", new[] { "Плюётся гнилью и поднимает мертвецов", "Spits rot and raises the dead", "喷吐腐液并唤起死者", "Escupe podredumbre y alza a los muertos" } },
            { "boss.demon", new[] { "Демон-слизень", "The Demon Slime", "恶魔史莱姆", "El demonio limo" } },
            { "boss.demon.rule", new[] { "Рубит тесаком всё перед собой и плюётся огнём. Держись сбоку", "Cleaves everything in front of him and spits fire. Stay at his side", "挥刀劈砍面前的一切并喷吐火焰。待在他身侧", "Parte todo lo que tiene delante y escupe fuego. Quédate a su lado" } },
            { "boss.frost", new[] { "Ледяной страж", "The Frost Guardian", "冰霜守卫", "El guardián de escarcha" } },
            { "boss.frost.rule", new[] { "Бьёт оземь — лёд разлетается кольцом и крестом. Пол скользкий", "Slams the ground: ice flies out in a ring and a cross. The floor is slippery", "重击地面：冰片呈环形和十字飞散。地面很滑", "Golpea el suelo: el hielo sale en anillo y en cruz. El suelo resbala" } },
            { "fx.split", new[] { "Делится!", "Splits!", "分裂！", "¡Se divide!" } },
            { "room.shop", new[] { "Лавка", "Shop", "商店", "Tienda" } },
            { "room.challenge", new[] { "Испытание · {0}", "Challenge · {0}", "试炼 · {0}", "Desafío · {0}" } },
            { "room.challenge.rule", new[] { "Три волны врагов, в награду — реликвия.", "Three waves of enemies, a relic as the reward.", "三波敌人，奖励一件遗物。", "Tres oleadas de enemigos; la recompensa es una reliquia." } },
            { "room.ambush", new[] { "Тихий зал", "Quiet Hall", "寂静大厅", "Sala silenciosa" } },
            { "room.ambush.rule", new[] { "Подозрительно тихо… Закон: {0}", "Suspiciously quiet… Law: {0}", "安静得可疑……法则：{0}", "Sospechosamente tranquilo… Ley: {0}" } },
            { "room.treasure", new[] { "Тайник", "Hidden Cache", "秘密宝库", "Escondite" } },
            { "room.treasure.rule", new[] { "Три сундука. Один из них кусается.", "Three chests. One of them bites.", "三个宝箱。其中一个会咬人。", "Tres cofres. Uno de ellos muerde." } },
            { "room.gamble", new[] { "Гача-терминал", "Gacha Terminal", "扭蛋终端", "Terminal gacha" } },
            { "room.gamble.rule", new[] { "[SYSTEM] принимает монеты. Удача не гарантирована.", "[SYSTEM] accepts coins. Luck not guaranteed.", "[SYSTEM]接受金币。不保证好运。", "[SYSTEM] acepta monedas. La suerte no está garantizada." } },
            { "obj.wave", new[] { "Волна {0}/{1} · врагов: {2}", "Wave {0}/{1} · enemies: {2}", "第{0}/{1}波 · 敌人：{2}", "Oleada {0}/{1} · enemigos: {2}" } },
            { "obj.quiet", new[] { "Тихо… слишком тихо. Выйди в центр зала", "Quiet… too quiet. Step into the middle", "安静……太安静了。走到大厅中央", "Silencio… demasiado. Ve al centro de la sala" } },
            { "obj.treasure", new[] { "Сундуки открываются сами — но один из них мимик", "Chests open on touch — but one is a mimic", "触碰即可打开宝箱——但其中一个是宝箱怪", "Los cofres se abren al tocarlos, pero uno es un mímico" } },
            { "obj.gamble", new[] { "E — сыграть за {0} монет (у тебя {1})", "E — play for {0} coins (you have {1})", "E——花{0}金币抽一次（你有{1}）", "E: jugar por {0} monedas (tienes {1})" } },
            { "toast.challenge", new[] { "Испытание пройдено!", "Challenge complete!", "试炼完成！", "¡Desafío superado!" } },
            { "toast.wave", new[] { "Волна {0}/{1}", "Wave {0}/{1}", "第{0}/{1}波", "Oleada {0}/{1}" } },
            { "toast.ambush", new[] { "Засада!", "Ambush!", "埋伏！", "¡Emboscada!" } },
            { "toast.mimic", new[] { "Это мимик!", "It's a mimic!", "是宝箱怪！", "¡Es un mímico!" } },
            { "toast.noCoins", new[] { "Не хватает монет", "Not enough coins", "金币不足", "No tienes monedas suficientes" } },
            { "gacha.nothing", new[] { "Пусто. [SYSTEM] благодарит за пожертвование", "Nothing. [SYSTEM] thanks you for the donation", "什么也没有。[SYSTEM]感谢你的捐赠", "Nada. [SYSTEM] agradece tu donación" } },
            { "gacha.coins", new[] { "Монеты!", "Coins!", "金币！", "¡Monedas!" } },
            { "gacha.heart", new[] { "Сердечки!", "Hearts!", "爱心！", "¡Corazones!" } },
            { "gacha.flask", new[] { "Колба!", "A flask!", "药瓶！", "¡Un frasco!" } },
            { "gacha.relic", new[] { "ДЖЕКПОТ: реликвия!", "JACKPOT: a relic!", "大奖：遗物！", "¡PREMIO GORDO: una reliquia!" } },
            { "gacha.bug", new[] { "ОШИБКА. Из терминала вылезли баги!", "ERROR. Bugs crawled out of the terminal!", "错误。终端里爬出了虫子！", "ERROR. ¡Del terminal salieron bichos!" } },
            { "hint.treasure", new[] { "Сундуки в тайнике открываются от касания. Один из них — мимик, будь готов к бою.", "Chests in the cache open on touch. One of them is a mimic — be ready to fight.", "宝库里的宝箱一碰就开。其中一个是宝箱怪——准备战斗。", "Los cofres del escondite se abren al tocarlos. Uno es un mímico: prepárate." } },
            { "hint.gamble", new[] { "Подойди к терминалу и нажми E. Каждая попытка дороже предыдущей.", "Walk up to the terminal and press E. Each pull costs more than the last.", "走到终端前按E。每次抽取都比上一次更贵。", "Acércate al terminal y pulsa E. Cada tirada cuesta más que la anterior." } },
            { "room.shop.rule", new[] { "Встань на товар, чтобы купить его за монеты", "Step on an item to buy it with coins", "站到商品上用金币购买", "Pisa un objeto para comprarlo con monedas" } },
            { "room.shrine", new[] { "Алтарь", "Shrine", "祭坛", "Altar" } },
            { "room.shrine.rule", new[] { "Реликвия в обмен на одно сердце навсегда", "A relic for one heart, forever", "以一颗心永久换取一件遗物", "Una reliquia a cambio de un corazón para siempre" } },
            { "room.fountain", new[] { "Фонтан", "Fountain", "泉水", "Fuente" } },
            { "room.fountain.rule", new[] { "Испей — и раны затянутся", "Drink and your wounds will close", "饮下泉水，伤口愈合", "Bebe y tus heridas sanarán" } },
            { "shop.coins", new[] { "{0} мон.", "{0} coins", "{0}金币", "{0} monedas" } },
            { "shop.heart", new[] { "-1 сердце", "-1 heart", "-1颗心", "-1 corazón" } },
            { "shop.free", new[] { "даром", "free", "免费", "gratis" } },
            { "shop.noMoney", new[] { "Не хватает монет", "Not enough coins", "金币不足", "No tienes monedas suficientes" } },
            { "shop.noHearts", new[] { "Слишком мало сердец", "Too few hearts", "生命太少了", "Tienes muy pocos corazones" } },
            { "shop.healItem", new[] { "Сердце", "Heart", "红心", "Corazón" } },
            { "toast.healed", new[] { "Раны затянулись", "Your wounds closed", "伤口愈合了", "Tus heridas sanaron" } },
            { "toast.regen", new[] { "Чистая работа: +½", "Clean room: +½", "无伤通过：回复半颗心", "Sala limpia: +½" } },
            { "toast.identified", new[] { "Колба: {0}!", "Flask: {0}!", "药瓶：{0}！", "Frasco: {0}!" } },
            { "up.unknown.name", new[] { "Неизвестная колба", "Unknown flask", "未知药瓶", "Frasco desconocido" } },
            { "up.unknown.desc", new[] { "Выпей — узнаешь, что внутри", "Drink it to find out", "喝下才知道是什么", "Bébelo para descubrirlo" } },
            { "obj.shop", new[] { "Монет: {0}. Встань на товар, чтобы купить", "Coins: {0}. Step on an item to buy it", "金币：{0}。站到商品上购买", "Monedas: {0}. Pisa un objeto para comprarlo" } },
            { "obj.shrine", new[] { "Встань на алтарь: реликвия за одно сердце", "Step on the shrine: a relic for one heart", "站上祭坛：以一颗心换遗物", "Pisa el altar: una reliquia por un corazón" } },
            { "obj.fountain", new[] { "Подойди к фонтану, чтобы вылечиться", "Walk to the fountain to heal", "走到泉水边治疗", "Acércate a la fuente para curarte" } },
            { "obj.next", new[] { "Дверь открыта", "The door is open", "门已打开", "La puerta está abierta" } },
            { "pause.coins", new[] { "Монеты: {0}", "Coins: {0}", "金币：{0}", "Monedas: {0}" } },
            { "end.floors", new[] { "Этаж: {0} из {1}", "Floor: {0} of {1}", "楼层：{0}/{1}", "Piso: {0} de {1}" } },
            { "end.floorEndless", new[] { "Этаж: {0}", "Floor: {0}", "楼层：{0}", "Piso: {0}" } },
            { "unlock.chaos", new[] { "режим «Хаос»", "Chaos mode", "混沌模式", "modo Caos" } },
            { "hint.shop", new[] { "Монеты падают с врагов. В лавке их можно потратить на реликвии и колбы.", "Enemies drop coins. Spend them in the shop on relics and flasks.", "敌人会掉落金币。在商店里用它们购买遗物和药瓶。", "Los enemigos sueltan monedas. Gástalas en la tienda en reliquias y frascos." } },
            { "hint.shrine", new[] { "Алтарь навсегда забирает одно сердце, но даёт реликвию.", "The shrine takes one heart forever, but gives a relic.", "祭坛会永久夺走一颗心，但给你一件遗物。", "El altar se lleva un corazón para siempre, pero da una reliquia." } },
            { "hint.elite", new[] { "Золотые враги — элита: крепче, но роняют больше монет.", "Golden enemies are elites: tougher, but they drop more coins.", "金色敌人是精英：更强壮，但掉落更多金币。", "Los enemigos dorados son élite: más duros, pero sueltan más monedas." } },
            { "hint.flask", new[] { "В каждом забеге колбы выглядят по-новому. Выпей, чтобы узнать, что внутри.", "Flasks look different every run. Drink one to learn what it does.", "每次冒险药瓶的样子都不同。喝下才知道效果。", "Los frascos cambian de aspecto en cada partida. Bebe para saber qué hacen." } },
            { "hint.floor", new[] { "Новый этаж: враги сильнее, а в конце ждёт босс.", "A new floor: enemies are stronger and a boss waits at the end.", "新的楼层：敌人更强，尽头有首领等待。", "Nuevo piso: los enemigos son más fuertes y al final espera un jefe." } },
            { "toast.bossDefeated", new[] { "{0} повержен!", "{0} is defeated!", "{0}被击败了！", "¡{0} ha caído!" } },
            { "pause.controls", new[] { "WASD — ход  ·  мышь — прицел  ·  ЛКМ — атака  ·  Shift / ПКМ — рывок  ·  E — говорить  ·  Esc / P — пауза", "WASD — move  ·  mouse — aim  ·  LMB — attack  ·  Shift / RMB — dash  ·  E — use  ·  Esc / P — pause", "WASD移动　鼠标瞄准　左键攻击　Shift或右键冲刺　E使用　Esc或P暂停", "WASD: moverse  ·  ratón: apuntar  ·  clic: atacar  ·  Shift / clic derecho: esquivar  ·  E: usar  ·  Esc / P: pausa" } },
            { "toast.konami", new[] { "Старая школа! +1 сердце и 30 монет", "Old school! +1 heart and 30 coins", "老派秘籍！+1颗心和30金币", "¡Vieja escuela! +1 corazón y 30 monedas" } },
            { "ctl.move", new[] { "ход", "move", "移动", "moverse" } },
            { "ctl.attack", new[] { "атака", "attack", "攻击", "atacar" } },
            { "ctl.dash", new[] { "рывок", "dash", "冲刺", "esquivar" } },
            { "ctl.pause", new[] { "пауза", "pause", "暂停", "pausa" } },
            { "ctl.use", new[] { "говорить", "use", "使用", "usar" } },
            { "ctl.map", new[] { "карта", "map", "地图", "mapa" } },
            { "room.secret.1", new[] { "Сохранение: Первая ночь", "Save: The First Night", "存档：第一夜", "Partida: La primera noche" } },
            { "room.secret.1.rule", new[] { "Ночь, когда Амелия впервые вставила картридж", "The night Amelia first put the cartridge in", "阿米莉亚第一次插入卡带的那个夜晚", "La noche en que Amelia metió el cartucho por primera vez" } },
            { "hud.secretCard", new[] { "ПОВРЕЖДЁННОЕ СОХРАНЕНИЕ", "CORRUPTED SAVE", "损坏的存档", "PARTIDA DAÑADA" } },
            { "obj.secret", new[] { "Осмотрись. Подходи к вещам со знаком !", "Look around. Walk up to things marked !", "四处看看。走近标有 ! 的东西", "Mira a tu alrededor. Acércate a lo que tenga !" } },
            { "toast.secret", new[] { "Стена рассыпалась пикселями — там проход!", "The wall crumbled into pixels — there's a passage!", "墙壁碎成了像素——那里有条通道！", "¡El muro se deshizo en píxeles: hay un pasadizo!" } },
            { "hint.secret", new[] { "Эта трещина — баг! Ударь по ней три раза.", "This crack is a bug! Hit it three times.", "这道裂缝是个漏洞！打它三下。", "¡Esta grieta es un bug! Golpéala tres veces." } },
            { "hint.memory", new[] { "Это не игра… это чьё-то настоящее воспоминание. Подходи к вещам.", "This isn't the game… it's someone's real memory. Walk up to things.", "这不是游戏……这是某人真实的回忆。走近那些东西看看。", "Esto no es el juego… es el recuerdo real de alguien. Acércate a las cosas." } },
            { "boss.line.1", new[] { "Нарушение правил обнаружено.", "Rule violation detected.", "检测到违规行为。", "Infracción de reglas detectada." } },
            { "boss.line.2", new[] { "Патч применён.", "Patch applied.", "补丁已应用。", "Parche aplicado." } },
            { "boss.line.3", new[] { "Игрок, вернись в отведённую зону!", "Player, return to your designated zone!", "玩家，回到指定区域！", "¡Jugador, vuelve a tu zona asignada!" } },
            { "boss.line.4", new[] { "Тебя тоже придётся переписать.", "You will have to be rewritten too.", "你也必须被重写。", "También tendré que reescribirte." } },
            { "boss.line.5", new[] { "Мир стабилен. Мир стабилен!", "The world is stable. The world is stable!", "世界稳定。世界稳定！", "El mundo es estable. ¡El mundo es estable!" } },
            { "boss.line.6", new[] { "Без законов всё рассыплется. Ты не понимаешь!", "Without laws everything falls apart. You don't understand!", "没有法则，一切都会崩塌。你不明白！", "Sin leyes todo se desmorona. ¡No lo entiendes!" } },
            { "boss.enraged", new[] { "Полный откат! Мир будет сброшен!", "Full rollback! The world will be reset!", "全面回滚！世界将被重置！", "¡Reversión total! ¡El mundo se reiniciará!" } },
            { "boss.death", new[] { "…Система… отключается…", "…System… shutting down…", "……系统……正在关闭……", "…Sistema… apagándose…" } },
            { "room.secret.0", new[] { "Сохранение: До игры", "Save: Before the Game", "存档：游戏之前", "Partida: Antes del juego" } },
            { "room.secret.0.rule", new[] { "Солнечный день. Картридж ещё лежит в коробке", "A sunny day. The cartridge is still in its box", "晴朗的一天。卡带还躺在盒子里", "Un día de sol. El cartucho sigue en su caja" } },
            { "room.secret.2", new[] { "Сохранение: Пустая комната", "Save: The Empty Room", "存档：空房间", "Partida: La habitación vacía" } },
            { "room.secret.2.rule", new[] { "Год спустя. Консоль включается сама", "A year later. The console turns itself on", "一年后。主机自己开了机", "Un año después. La consola se enciende sola" } },
            { "lore.dream.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.dream.calendar.text", new[] { "Обведена суббота: «Фестиваль с Адамом!!!» Рядом нарисована лисья маска.", "Saturday circled: \"Festival with Adam!!!\" A fox mask is drawn next to it.", "星期六被圈起来：“和亚当去夏日祭！！！”旁边画着一个狐狸面具。", "Sábado rodeado: «¡¡¡Festival con Adam!!!» Al lado hay dibujada una máscara de zorro." } },
            { "lore.dream.tv", new[] { "Телевизор", "TV", "电视", "Televisor" } },
            { "lore.dream.tv.text", new[] { "По телевизору аниме про героя, которого затянуло в игру. Амелия смеётся: «Вот бы и мне так».", "An anime is on TV about a hero pulled into a game. Amelia laughs: \"I wish that happened to me.\"", "电视上在放一部动画，讲一个被吸进游戏的英雄。阿米莉亚笑着说：“要是我也能这样就好了。”", "En la tele echan un anime sobre un héroe absorbido por un juego. Amelia se ríe: «Ojalá me pasara a mí»." } },
            { "lore.dream.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.dream.photo.text", new[] { "Семейное фото: мама, Амелия и Адам. Подпись: «Мы всегда будем вместе».", "A family photo: Mom, Amelia and Adam. Caption: \"We'll always be together.\"", "全家福：妈妈、阿米莉亚和亚当。题字：“我们永远在一起。”", "Foto familiar: mamá, Amelia y Adam. Pie: «Siempre estaremos juntos»." } },
            { "lore.dream.desk", new[] { "Стол", "Desk", "书桌", "Escritorio" } },
            { "lore.dream.desk.text", new[] { "На столе — ещё запечатанная коробка с барахолки. Внутри что-то тяжёлое и тёплое.", "On the desk, a still-sealed box from the flea market. Inside, something heavy and warm.", "桌上放着一个从跳蚤市场买来、还没拆封的盒子。里面有个又重又暖的东西。", "Sobre la mesa, una caja aún precintada del rastro. Dentro, algo pesado y cálido." } },
            { "lore.silence.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.silence.calendar.text", new[] { "Календарь так и остался на той субботе. Фестиваль прошёл без них.", "The calendar is still on that Saturday. The festival went on without them.", "日历还停在那个星期六。夏日祭在没有他们的情况下结束了。", "El calendario sigue en aquel sábado. El festival pasó sin ellos." } },
            { "lore.silence.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.silence.photo.text", new[] { "Фото с фестиваля лежит лицом вниз. На обороте почерком Адама: «Вернись».", "The festival photo lies face down. On the back, in Adam's handwriting: \"Come back.\"", "夏日祭的照片扣着放着。背面是亚当的字迹：“回来吧。”", "La foto del festival está boca abajo. En el reverso, con letra de Adam: «Vuelve»." } },
            { "lore.silence.bed", new[] { "Кровать", "Bed", "床", "Cama" } },
            { "lore.silence.bed.text", new[] { "Кровать Амелии заправлена. Мама каждую неделю меняет бельё — «на всякий случай».", "Amelia's bed is made. Mom changes the sheets every week, \"just in case\".", "阿米莉亚的床铺得整整齐齐。妈妈每周都换床单——“以防万一”。", "La cama de Amelia está hecha. Mamá cambia las sábanas cada semana, «por si acaso»." } },
            { "lore.silence.boxes", new[] { "Коробки", "Boxes", "纸箱", "Cajas" } },
            { "lore.silence.boxes.text", new[] { "Коробки подписаны маркером: «Вещи Амелии. НЕ ВЫБРАСЫВАТЬ».", "Boxes labeled in marker: \"Amelia's things. DO NOT THROW AWAY.\"", "箱子上用马克笔写着：“阿米莉亚的东西。不许扔。”", "Cajas rotuladas con rotulador: «Cosas de Amelia. NO TIRAR»." } },
            { "lore.silence.fridge", new[] { "Холодильник", "Fridge", "冰箱", "Nevera" } },
            { "lore.silence.fridge.text", new[] { "Записка от мамы: «Адам, поешь. И выключи наконец эту консоль, она гудит всю ночь».", "A note from Mom: \"Adam, eat something. And switch that console off, it hums all night.\"", "妈妈留的字条：“亚当，吃点东西。还有，把那台主机关了吧，它整晚都在嗡嗡响。”", "Nota de mamá: «Adam, come algo. Y apaga de una vez esa consola, zumba toda la noche»." } },
            { "lore.silence.computer", new[] { "Консоль", "Console", "主机", "Consola" } },
            { "lore.silence.computer.text", new[] { "Консоль выключена из розетки — и всё равно светится: «RULECRAWL. Игрок 2 найден. Загрузка…»", "The console is unplugged — and still glowing: \"RULECRAWL. Player 2 found. Loading…\"", "主机的插头已经拔了——却仍在发光：“RULECRAWL。已找到玩家2。正在载入……”", "La consola está desenchufada y aun así brilla: «RULECRAWL. Jugador 2 encontrado. Cargando…»" } },
            { "lore.page", new[] { "Последняя запись", "The Last Entry", "最后的记录", "La última entrada" } },
            { "lore.page.text", new[] { "Почерк Амелии: «Адам, если ты собрал мои сохранения — значит, ты здесь. Администратор — это я. Система надела на меня корону, когда я дошла до конца. Сломай её. И пойдём домой».", "Amelia's handwriting: \"Adam, if you've gathered my saves, you're here. The Administrator is me. The System put the crown on me when I reached the end. Break it. And let's go home.\"", "阿米莉亚的字迹：“亚当，如果你集齐了我的存档——说明你已经在这里了。管理员就是我。我走到尽头时，系统给我戴上了王冠。打碎它。然后我们回家。”", "Letra de Amelia: «Adam, si has reunido mis partidas, es que estás aquí. El Administrador soy yo. El Sistema me puso la corona cuando llegué al final. Rómpela. Y volvamos a casa»." } },
            { "toast.allMemories", new[] { "Все сохранения собраны! Открыта истинная концовка", "All saves found! The true ending is open", "已集齐所有存档！真结局已开启", "¡Todas las partidas encontradas! Se abre el final verdadero" } },
            { "boss.mem.1", new[] { "Это сохранение удалено. Откуда оно у тебя?", "That save was deleted. Where did you get it?", "那个存档已被删除。你从哪儿拿到的？", "Esa partida fue borrada. ¿De dónde la has sacado?" } },
            { "boss.mem.2", new[] { "Адам?.. Нет. Игрок, назови себя!", "Adam?.. No. Player, identify yourself!", "亚当？……不。玩家，报上名来！", "¿Adam?.. No. ¡Jugador, identifícate!" } },
            { "boss.mem.3", new[] { "Я почти вспомнила… Нет! Правила важнее!", "I almost remembered… No! The rules matter more!", "我差点想起来了……不！规则更重要！", "Casi lo recordé… ¡No! ¡Las reglas importan más!" } },
            { "ending.label", new[] { "КОНЦОВКА", "ENDING", "结局", "FINAL" } },
            { "end.ending", new[] { "Концовка: {0} ({1}/{2})", "Ending: {0} ({1}/{2})", "结局：{0}（{1}/{2}）", "Final: {0} ({1}/{2})" } },
            { "ending.0.name", new[] { "Выход из игры", "Log Out", "退出游戏", "Cerrar sesión" } },
            { "ending.0.1", new[] { "Администратор рассыпался на строки кода. [СИСТЕМА] Игрок может выйти.", "The Administrator crumbled into lines of code. [SYSTEM] The player may log out.", "管理员崩解成一行行代码。[系统] 玩家可以退出了。", "El Administrador se deshizo en líneas de código. [SISTEMA] El jugador puede salir." } },
            { "ending.0.3", new[] { "Мир перестроился, двери снова ждут. Где-то в его стенах всё ещё лежат её сохранения.", "The world rebuilt itself, the doors are waiting again. Somewhere in its walls her saves still lie.", "世界重组了，门又在等待。她的存档仍藏在墙壁的某处。", "El mundo se reconstruyó, las puertas vuelven a esperar. En algún lugar de sus muros siguen sus partidas." } },
            { "ending.1.name", new[] { "Новый Администратор", "The New Administrator", "新任管理员", "El nuevo Administrador" } },
            { "ending.1.1", new[] { "Ты показал Администратору сохранение из настоящего мира.", "You showed the Administrator a save from the real world.", "你给管理员看了来自真实世界的存档。", "Le mostraste al Administrador una partida del mundo real." } },
            { "ending.1.2", new[] { "Корона из правил села на голову Адама. Пикси вздохнула: «Ну вот. Теперь ты начальник».", "The crown of rules settled on Adam's head. Pixie sighed: \"Well. Now you're the boss.\"", "规则之冠落在了亚当的头上。皮克西叹了口气：“好吧。现在你是老大了。”", "La corona de reglas se posó en la cabeza de Adam. Pixie suspiró: «Bueno. Ahora el jefe eres tú»." } },
            { "ending.1.3", new[] { "Прежний Администратор ушёл, так и не вспомнив, кем была. Остальные сохранения всё ещё где-то в стенах.", "The old Administrator left without remembering who she was. The other saves are still somewhere in the walls.", "前任管理员离开了，始终没想起自己是谁。其余的存档仍藏在墙壁的某处。", "El antiguo Administrador se fue sin recordar quién era. Las demás partidas siguen en algún lugar de los muros." } },
            { "ending.2.name", new[] { "Домой вместе", "Home Together", "一起回家", "A casa juntos" } },
            { "ending.2.1", new[] { "Ты вернул Администратору всё, что стёрла Система.", "You gave the Administrator back everything the System erased.", "你把系统抹去的一切都还给了管理员。", "Le devolviste al Administrador todo lo que el Sistema había borrado." } },
            { "ending.2.2", new[] { "Корона из правил треснула. Под ней была Амелия.", "The crown of rules cracked. Under it was Amelia.", "规则之冠裂开了。王冠之下是阿米莉亚。", "La corona de reglas se agrietó. Debajo estaba Amelia." } },
            { "ending.2.3", new[] { "Адам открыл глаза у старой консоли. На экране: [ИГРА ПРОЙДЕНА].", "Adam opened his eyes at the old console. On the screen: [GAME CLEAR].", "亚当在旧主机前睁开眼睛。屏幕上显示：[游戏通关]。", "Adam abrió los ojos junto a la vieja consola. En la pantalla: [JUEGO COMPLETADO]." } },
            { "ending.2.4", new[] { "Картридж они убрали в коробку. Подальше. На всякий случай.", "They put the cartridge in a box. Far away. Just in case.", "他们把卡带收进了盒子。放得远远的。以防万一。", "Guardaron el cartucho en una caja. Bien lejos. Por si acaso." } },
            { "ending.2.5", new[] { "Спасибо, что дошёл до конца.", "Thank you for reaching the end.", "感谢你走到最后。", "Gracias por llegar hasta el final." } },
            { "codex.story", new[] { "ИСТОРИЯ", "STORY", "故事", "HISTORIA" } },
            { "codex.watch", new[] { "СМОТРЕТЬ", "WATCH", "观看", "VER" } },
            { "codex.unknownMemory", new[] { "Ещё не найдено. Ищи баги в стенах", "Not found yet. Look for bugs in the walls", "尚未找到。寻找墙上的漏洞", "Aún no encontrada. Busca bugs en las paredes" } },
            { "ending.0.how", new[] { "Победи Администратора", "Defeat the Administrator", "击败管理员", "Derrota al Administrador" } },
            { "ending.1.how", new[] { "Победи, найдя сохранение в том же забеге", "Win after finding a save in the same run", "在同一轮中找到存档并获胜", "Gana tras encontrar una partida en la misma carrera" } },
            { "ending.2.how", new[] { "Собери все три сохранения и победи", "Find all three saves and win", "集齐三个存档并获胜", "Reúne las tres partidas y gana" } },
            { "ending.0.2", new[] { "Дверь наружу открылась… но за ней оказалась ещё одна дверь.", "The way out opened… but behind it was another door.", "出口的门打开了……可门后又是一扇门。", "La salida se abrió… pero detrás había otra puerta." } },
            { "cs.skip", new[] { "Esc — пропустить", "Esc — skip", "Esc跳过", "Esc: saltar" } },
            { "cs.skipTouch", new[] { "Пропустить ›", "Skip ›", "跳过 ›", "Saltar ›" } },
            { "touch.dash", new[] { "РЫВОК", "DASH", "冲刺", "ESQUIVA" } },
            { "touch.use", new[] { "ГОВОРИТЬ", "USE", "互动", "USAR" } },
            { "touch.map", new[] { "КАРТА", "MAP", "地图", "MAPA" } },
            { "cs.mem.0", new[] { "Солнце, запах карри и шум телевизора. Всё ещё хорошо.", "Sunlight, the smell of curry, the TV murmuring. Everything is still fine.", "阳光、咖喱的香味和电视的声音。一切都还好好的。", "Sol, olor a curry y el murmullo de la tele. Todo sigue bien." } },
            { "cs.mem.1", new[] { "Ночь. Гудит старая консоль. На экране заставка, которую никто раньше не видел.", "Night. The old console hums. On the screen, a title nobody has seen before.", "夜晚。旧主机嗡嗡作响。屏幕上是谁都没见过的标题画面。", "Noche. La vieja consola zumba. En la pantalla, un título que nadie ha visto antes." } },
            { "cs.mem.2", new[] { "Тишина. Прошёл год. Консоль мигает в темноте сама по себе.", "Silence. A year has passed. The console blinks in the dark on its own.", "寂静。一年过去了。主机在黑暗中自己闪烁。", "Silencio. Ha pasado un año. La consola parpadea sola en la oscuridad." } },
            { "cs.meet.1", new[] { "Новый игрок. Добро пожаловать в тронный зал. Я — Администратор.", "A new player. Welcome to the throne hall. I am the Administrator.", "新玩家。欢迎来到王座厅。我是管理员。", "Un jugador nuevo. Bienvenido al salón del trono. Soy el Administrador." } },
            { "cs.meet.2", new[] { "Каждая дверь — мой патч. Каждый закон держит мир, который иначе рассыплется.", "Every door is my patch. Every law holds up a world that would otherwise fall apart.", "每扇门都是我的补丁。每条法则都撑着这个本会崩塌的世界。", "Cada puerta es un parche mío. Cada ley sostiene un mundo que, si no, se desmoronaría." } },
            { "cs.meet.mem", new[] { "Ты открывал повреждённые сохранения. Это запрещено.", "You opened corrupted saves. That is forbidden.", "你打开了损坏的存档。这是被禁止的。", "Abriste partidas dañadas. Está prohibido." } },
            { "cs.meet.all", new[] { "Ты видел её комнату… Нет. Я не помню никакой комнаты!", "You saw her room… No. I don't remember any room!", "你看到了她的房间……不。我不记得什么房间！", "Viste su habitación… No. ¡No recuerdo ninguna habitación!" } },
            { "cs.meet.3", new[] { "Тест на совместимость: все законы сразу!", "Compatibility test: every law at once!", "兼容性测试：所有法则同时生效！", "Prueba de compatibilidad: ¡todas las leyes a la vez!" } },
            { "cs.e0.1", new[] { "Ошибка… администратор… не найден…", "Error… administrator… not found…", "错误……管理员……未找到……", "Error… administrador… no encontrado…" } },
            { "cs.e0.2", new[] { "[СИСТЕМА] Назначен новый Администратор. Загрузка мира…", "[SYSTEM] A new Administrator has been assigned. Loading the world…", "[系统] 已任命新的管理员。正在载入世界……", "[SISTEMA] Se ha asignado un nuevo Administrador. Cargando el mundo…" } },
            { "cs.e1.1", new[] { "Добьёшь меня? Тогда трон достанется тебе.", "Will you finish me? Then the throne goes to you.", "要给我最后一击吗？那王座就归你了。", "¿Vas a acabar conmigo? Entonces el trono será tuyo." } },
            { "cs.e1.2", new[] { "…Комната? Солнце в окне? Я… там была?", "…A room? Sunlight in the window? I… was there?", "……房间？窗外的阳光？我……去过那里？", "…¿Una habitación? ¿Sol en la ventana? ¿Yo… estuve allí?" } },
            { "cs.e1.3", new[] { "Тогда держи корону. Мне пора вспоминать.", "Then take the crown. It's time for me to remember.", "那王冠给你吧。我该去回忆了。", "Entonces toma la corona. Es hora de que recuerde." } },
            { "cs.e2.1", new[] { "До игры… первая ночь… пустая комната… Это же мои сохранения.", "Before the game… the first night… the empty room… These are my saves.", "游戏之前……第一夜……空房间……这些是我的存档。", "Antes del juego… la primera noche… la habitación vacía… Son mis partidas." } },
            { "cs.e2.2", new[] { "Адам?.. Ты вырос. Сколько я здесь пробыла?", "Adam?.. You've grown. How long was I in here?", "亚当？……你长大了。我在这里待了多久？", "¿Adam?.. Has crecido. ¿Cuánto tiempo he estado aquí?" } },
            { "cs.e2.3", new[] { "Эй, соня. Мама зовёт ужинать. Фестиваль ведь сегодня?", "Hey, sleepyhead. Mom says dinner's ready. The festival's today, right?", "嘿，小懒虫。妈妈叫吃饭了。夏日祭是今天吧？", "Eh, dormilón. Mamá dice que la cena está lista. El festival es hoy, ¿no?" } },
            { "cs.e2.4", new[] { "Сегодня. С возвращением, сестрёнка.", "Today. Welcome back, sis.", "是今天。欢迎回来，姐姐。", "Hoy. Bienvenida, hermana." } },
            { "name.ren", new[] { "Адам", "Adam", "亚当", "Adam" } },
            { "name.yuki", new[] { "Амелия", "Amelia", "阿米莉亚", "Amelia" } },
            { "name.pixie", new[] { "Пикси", "Pixie", "皮克西", "Pixie" } },
            { "name.system", new[] { "[СИСТЕМА]", "[SYSTEM]", "[系统]", "[SISTEMA]" } },
            { "pixie.say", new[] { "Пикси: {0}", "Pixie: {0}", "皮克西：{0}", "Pixie: {0}" } },
            { "pixie.intro.1", new[] { "Опять новенький?! Ну ладно, ладно… Я — Пикси, навигатор Системы. Добро пожаловать в RULECRAWL!", "A newbie again?! Fine, fine… I'm Pixie, the System's navigator. Welcome to RULECRAWL!", "又来一个新人？！好吧好吧……我是皮克西，系统的领航妖精。欢迎来到RULECRAWL！", "¡¿Otro novato?! Vale, vale… Soy Pixie, la navegadora del Sistema. ¡Bienvenido a RULECRAWL!" } },
            { "pixie.intro.2", new[] { "Запоминай: за каждой дверью Система меняет правила. Читай закон над дверью — и выживай.", "Listen: behind every door the System changes the rules. Read the law over the door, then survive.", "记住：每扇门后系统都会改变规则。看清门上的法则——然后活下去。", "Escucha: tras cada puerta el Sistema cambia las reglas. Lee la ley sobre la puerta y sobrevive." } },
            { "pixie.intro.3", new[] { "Дойдёшь до Администратора — сможешь выйти из игры. Наверное. Пока ещё никто не выходил.", "Reach the Administrator and you can log out. Probably. Nobody has so far.", "打到管理员那里，你就能退出游戏。大概吧。到现在还没人出去过。", "Llega al Administrador y podrás salir del juego. Probablemente. Nadie lo ha hecho todavía." } },
            { "pixie.intro.4", new[] { "И ещё: трещины в стенах — это баги. Ударь трижды. В багах иногда застревают чужие сохранения…", "Oh, and cracks in the walls are bugs. Hit them three times. Sometimes other people's saves get stuck in bugs…", "还有：墙上的裂缝是漏洞。打三下。漏洞里有时会卡着别人的存档……", "Y otra cosa: las grietas de las paredes son bugs. Golpéalas tres veces. A veces hay partidas de otros atrapadas en ellas…" } },
            { "prologue.1", new[] { "Год назад пропала моя сестра Амелия. Полиция говорит — сбежала. Я в это не верю.", "A year ago my sister Amelia vanished. The police say she ran away. I don't believe it.", "一年前，我的姐姐阿米莉亚失踪了。警察说她离家出走了。我不相信。", "Hace un año desapareció mi hermana Amelia. La policía dice que se escapó. No me lo creo." } },
            { "prologue.2", new[] { "От неё остались только старая консоль и картридж без надписи. Каждую ночь консоль включается сама.", "All she left was an old console and an unlabeled cartridge. Every night the console turns itself on.", "她只留下一台旧主机和一张没有标签的卡带。每天夜里，主机都会自己开机。", "Solo dejó una consola vieja y un cartucho sin etiqueta. Cada noche la consola se enciende sola." } },
            { "prologue.3", new[] { "Опять… Амелия, это ты?", "Again… Amelia, is that you?", "又来了……阿米莉亚，是你吗？", "Otra vez… Amelia, ¿eres tú?" } },
            { "prologue.card", new[] { "ИГРОК НАЙДЕН", "PLAYER FOUND", "已找到玩家", "JUGADOR ENCONTRADO" } },
            { "prologue.4", new[] { "Добро пожаловать в RULECRAWL. Выбор аватара… принят. Загрузка игрока.", "Welcome to RULECRAWL. Choosing an avatar… accepted. Loading the player.", "欢迎来到RULECRAWL。选择化身……已确认。正在载入玩家。", "Bienvenido a RULECRAWL. Eligiendo avatar… aceptado. Cargando jugador." } },
            { "prologue.5", new[] { "Что?! Экран… меня тянет внутрь!", "What?! The screen… it's pulling me in!", "什么？！屏幕……在把我吸进去！", "¡¿Qué?! La pantalla… ¡me está arrastrando dentro!" } },
            { "prologue.6", new[] { "Так Адам попал в игру, из которой не вернулась его сестра.", "That is how Adam got into the game his sister never came back from.", "就这样，亚当进入了那个他姐姐再也没能回来的游戏。", "Así entró Adam en el juego del que su hermana nunca volvió." } },
            { "codex.prologue", new[] { "ПРОЛОГ", "PROLOGUE", "序章", "PRÓLOGO" } },
            { "world.retro", new[] { "Версия 1.0", "Version 1.0", "1.0版", "Versión 1.0" } },
            { "world.retro.rule", new[] { "Забытая первая версия мира. Тут правит Король слизней", "The forgotten first version of the world. The Slime King rules here", "被遗忘的世界初版。史莱姆之王在此称王", "La primera versión olvidada del mundo. Aquí manda el Rey Limo" } },
            { "world.caves", new[] { "Глубинные пещеры", "The Deep Caves", "深渊洞窟", "Las cuevas profundas" } },
            { "world.caves.rule", new[] { "Ледяное и огненное ядро мира. Их стерегут Ледяной страж и Демон-слизень", "The world's ice and fire cores, guarded by the Frost Guardian and the Demon Slime", "世界的冰之核与火之核，由冰霜守卫和恶魔史莱姆看守", "Los núcleos de hielo y fuego del mundo, custodiados por el Guardián de escarcha y el Demonio limo" } },
            { "world.retro.system", new[] { "Предупреждение: загружена устаревшая версия 1.0. Цвета не поддерживаются.", "Warning: outdated version 1.0 loaded. Colours are not supported.", "警告：已载入过时的1.0版。不支持彩色。", "Aviso: cargada la versión obsoleta 1.0. Los colores no son compatibles." } },
            { "world.retro.pixie", new[] { "Ой, всё зелёное! Здесь Система держит старые баги. Слизни делятся от ударов — не сдавайся!", "Eek, everything's green! This is where the System keeps its old bugs. Slimes split when hit — don't give up!", "哇，全是绿色的！系统把旧漏洞都关在这里。史莱姆挨打会分裂——别放弃！", "¡Uy, todo es verde! Aquí guarda el Sistema sus bugs viejos. Los limos se dividen al golpearlos: ¡no te rindas!" } },
            { "world.caves.system", new[] { "Вход в ядро мира. Температура: нестабильна. Игрокам вход не рекомендован.", "Entering the world's core. Temperature: unstable. Players are advised to keep out.", "正在进入世界核心。温度：不稳定。不建议玩家进入。", "Entrando en el núcleo del mundo. Temperatura: inestable. No se recomienda la entrada de jugadores." } },
            { "world.caves.pixie", new[] { "Брр… сначала лёд, потом огонь. Кристаллы разбивай — они замораживают монстров. А магму не трогай вблизи!", "Brr… ice first, then fire. Break the crystals — they freeze monsters. And don't touch the magma up close!", "呜……先是冰，再是火。打碎水晶——能冻住怪物。岩浆石可别在近处碰！", "Brr… primero hielo, luego fuego. Rompe los cristales: congelan a los monstruos. ¡Y no toques el magma de cerca!" } },
            { "hud.worldCard", new[] { "НОВЫЙ МИР", "A NEW WORLD", "新的世界", "UN MUNDO NUEVO" } },
            { "hud.worldRoom", new[] { "{0} · комната {1}", "{0} · room {1}", "{0} · 第{1}个房间", "{0} · sala {1}" } },
            { "hud.worldBoss", new[] { "{0} · босс", "{0} · boss", "{0} · 首领", "{0} · jefe" } },
            { "boss.slime", new[] { "Король слизней", "The Slime King", "史莱姆之王", "El Rey Limo" } },
            { "boss.slime.rule", new[] { "Прыгает на тебя, каждое приземление — волна. Большие прыжки приносят слизней", "Leaps at you, every landing sends a wave. Big leaps bring slimes", "朝你跳来，每次落地都会掀起冲击波。大跳会带来史莱姆", "Salta hacia ti, cada aterrizaje lanza una onda. Los saltos grandes traen limos" } },
            { "toast.slimes", new[] { "Большой слизень! Каждый удар делит его надвое", "A big slime! Every hit splits it in two", "大史莱姆！每次攻击都会让它一分为二", "¡Un limo grande! Cada golpe lo divide en dos" } },
            { "toast.spikesOff", new[] { "Рычаг щёлкнул — шипы отключены", "The lever clicked — the spikes are off", "拉杆咔哒一声——尖刺已关闭", "La palanca hizo clic: los pinchos están desactivados" } },
            { "toast.cache", new[] { "Рычаг открыл тайник!", "The lever opened a hidden cache!", "拉杆打开了一个隐藏宝箱！", "¡La palanca abrió un escondite!" } },
            { "toast.maxHeart", new[] { "+1 сердце", "+1 heart", "+1 颗心", "+1 corazón" } },
            { "npc.mio.name", new[] { "Мио", "Mio", "澪", "Mio" } },
            { "npc.mio.1", new[] { "О, живой игрок! Я Мио. Застряла тут три недели… или три года? Время в игре идёт странно.", "Oh, a living player! I'm Mio. I've been stuck here three weeks… or three years? Time runs strangely in here.", "哦，是活着的玩家！我叫澪。我被困在这里三个星期了……还是三年？游戏里的时间很奇怪。", "¡Oh, un jugador vivo! Soy Mio. Llevo atrapada aquí tres semanas… ¿o tres años? Aquí el tiempo pasa raro." } },
            { "npc.mio.2", new[] { "Слышал про Администратора? Говорят, он тоже когда-то был игроком. Прошёл всё — и не смог выйти.", "Heard about the Administrator? They say he was a player once. Cleared everything — and couldn't leave.", "听说过管理员吗？据说他以前也是玩家。通关了一切——却出不去了。", "¿Has oído hablar del Administrador? Dicen que también fue jugador. Lo superó todo… y no pudo salir." } },
            { "npc.mio.gift", new[] { "Держи монеты. Мне они всё равно не помогут — я боюсь открывать двери.", "Take these coins. They won't help me anyway — I'm scared to open the doors.", "拿着这些金币吧。反正对我也没用——我不敢开门。", "Toma estas monedas. A mí no me sirven: me da miedo abrir las puertas." } },
            { "npc.mio.again0", new[] { "Удачи там, за дверью. И возвращайся живым!", "Good luck behind the door. Come back alive!", "门那边祝你好运。一定要活着回来！", "Suerte tras la puerta. ¡Vuelve con vida!" } },
            { "npc.mio.again1", new[] { "Если найдёшь выход — расскажи и мне, ладно?", "If you find the way out, tell me too, okay?", "如果找到出口，也告诉我一声，好吗？", "Si encuentras la salida, dímelo también, ¿vale?" } },
            { "npc.doc.name", new[] { "Док", "Doc", "医生", "Doc" } },
            { "npc.doc.1", new[] { "Не пугайся, я лечебный NPC. Раньше был обычным программистом. Теперь… вот.", "Don't be scared, I'm a healer NPC. I used to be a regular programmer. Now… this.", "别怕，我是治疗型NPC。以前只是个普通程序员。现在……就这样了。", "No te asustes, soy un PNJ sanador. Antes era un programador normal. Ahora… esto." } },
            { "npc.doc.2", new[] { "Законы — это заплатки. Мир трещит по швам, и Администратор латает его каждой дверью.", "The laws are patches. The world is coming apart at the seams, and the Administrator patches it with every door.", "法则就是补丁。世界正在从接缝处裂开，管理员用每一扇门来修补它。", "Las leyes son parches. El mundo se rompe por las costuras y el Administrador lo remienda con cada puerta." } },
            { "npc.doc.3", new[] { "Странно: в логах Администратор пишет о себе «она». Наверное, баг.", "Odd thing: in the logs the Administrator calls himself \"she\". Must be a bug.", "奇怪的是：日志里管理员称自己为“她”。大概是个漏洞吧。", "Qué raro: en los registros el Administrador se llama a sí mismo «ella». Será un bug." } },
            { "npc.doc.gift", new[] { "Стой смирно. Вот так — как новенький.", "Hold still. There — good as new.", "别动。好了——跟新的一样。", "Quieto. Así, como nuevo." } },
            { "npc.doc.again0", new[] { "Береги сердца. Новых у меня не осталось.", "Take care of your hearts. I'm out of new ones.", "爱惜你的心。我这里已经没有新的了。", "Cuida tus corazones. No me quedan nuevos." } },
            { "npc.beta.name", new[] { "Бета", "Beta", "贝塔", "Beta" } },
            { "npc.beta.1", new[] { "Ты из новой версии? С цветами?! Я — бета-тестер. Меня забыли удалить при обновлении.", "You're from the new version? With colours?! I'm a beta tester. They forgot to delete me in the update.", "你是新版本来的？有颜色的那种？！我是测试员。更新时他们忘了删掉我。", "¿Vienes de la versión nueva? ¡¿Con colores?! Soy un probador beta. Se olvidaron de borrarme en la actualización." } },
            { "npc.beta.2", new[] { "Король слизней ждёт в конце. Прыгает высоко, а на третий прыжок — ещё выше. Отходи, когда он взлетает.", "The Slime King waits at the end. He jumps high, and every third jump higher still. Back off when he takes off.", "史莱姆之王在尽头。他跳得很高，每第三下跳得更高。他起跳时就后退。", "El Rey Limo espera al final. Salta alto, y cada tercer salto aún más. Aléjate cuando despegue." } },
            { "npc.beta.gift", new[] { "Возьми лишнее сердце. В версии 1.0 они ещё стоили копейки.", "Take a spare heart. In version 1.0 they were still dirt cheap.", "拿去一颗备用的心。在1.0版里它们还便宜得很。", "Toma un corazón de sobra. En la versión 1.0 todavía costaban cuatro perras." } },
            { "npc.beta.again0", new[] { "Пип-пип. Это я так здороваюсь в 8 битах.", "Beep-beep. That's how I say hi in 8 bits.", "哔哔。这是我在8位世界打招呼的方式。", "Bip-bip. Así saludo en 8 bits." } },
            { "npc.goro.name", new[] { "Горо", "Goro", "五郎", "Goro" } },
            { "npc.goro.1", new[] { "Эй, осторожно! Здесь, внизу, держится весь мир: ледяное ядро и огненное. Я их сторожу. Ну, пытаюсь.", "Hey, careful! Down here the whole world rests on two cores, ice and fire. I guard them. Well, I try.", "嘿，小心！整个世界就靠这下面的两个核心撑着：冰之核和火之核。我在看守它们。嗯，尽力而为。", "¡Eh, cuidado! Aquí abajo se sostiene todo el mundo: el núcleo de hielo y el de fuego. Yo los vigilo. Bueno, lo intento." } },
            { "npc.goro.2", new[] { "Ледяной страж бьёт оземь — лёд летит кругом и крестом. Демон рубит перед собой. Держись у него за спиной.", "The Frost Guardian slams the ground — ice flies in a ring and a cross. The Demon cleaves in front of him. Stay behind him.", "冰霜守卫重击地面——冰片呈环形和十字飞出。恶魔向前劈砍。待在他身后。", "El Guardián de escarcha golpea el suelo: el hielo sale en anillo y en cruz. El Demonio corta lo que tiene delante. Quédate a su espalda." } },
            { "npc.goro.gift", new[] { "Вот, бери. Монеты и горячий чай. Пещеры не любят слабаков.", "Here, take this. Coins and hot tea. The caves don't like weaklings.", "来，拿着。金币和热茶。洞窟可不喜欢弱者。", "Toma. Monedas y té caliente. A las cuevas no les gustan los débiles." } },
            { "npc.goro.again0", new[] { "Кристаллы бей смело. Магму — издалека!", "Smash the crystals freely. The magma — from afar!", "水晶尽管打。岩浆石——离远点！", "Rompe los cristales sin miedo. El magma, ¡desde lejos!" } },
            { "npc.angel.name", new[] { "Хранитель фонтана", "Fountain Keeper", "泉水守护者", "Guardián de la fuente" } },
            { "npc.angel.1", new[] { "Этот фонтан Система забыла запатчить. Пей сколько хочешь.", "The System forgot to patch this fountain. Drink all you like.", "系统忘了给这座泉水打补丁。尽情喝吧。", "El Sistema olvidó parchear esta fuente. Bebe cuanto quieras." } },
            { "npc.angel.2", new[] { "Год назад здесь прошла девушка. Она тоже искала выход… а нашла трон.", "A girl passed through here a year ago. She was looking for the way out too… and found a throne.", "一年前有个女孩经过这里。她也在找出口……却找到了王座。", "Hace un año pasó por aquí una chica. También buscaba la salida… y encontró un trono." } },
            { "npc.angel.again0", new[] { "Вода чистая. Законы — нет.", "The water is clean. The laws are not.", "水是干净的。法则却不是。", "El agua está limpia. Las leyes no." } },
            { "npc.merchant.name", new[] { "Торговец", "Merchant", "商人", "Mercader" } },
            { "npc.merchant.1", new[] { "Монеты не пахнут — даже пиксельные. Выбирай, игрок!", "Coins don't smell — not even pixel ones. Take your pick, player!", "金币不会有味道——像素金币也一样。挑吧，玩家！", "El dinero no huele, ni siquiera el de píxeles. ¡Elige, jugador!" } },
            { "npc.merchant.2", new[] { "Скидок нет. Система запрещает.", "No discounts. The System forbids it.", "不打折。系统禁止。", "Sin descuentos. El Sistema lo prohíbe." } },
            { "npc.merchant.again0", new[] { "Ещё что-нибудь?", "Anything else?", "还要点别的吗？", "¿Algo más?" } },
            { "npc.merchant.again1", new[] { "Возвращайся, когда разбогатеешь.", "Come back when you're rich.", "等你有钱了再来。", "Vuelve cuando seas rico." } },
            { "lore.work.board", new[] { "Заметки", "Notes", "笔记", "Notas" } },
            { "lore.work.board.text", new[] { "Почерк Амелии: «Законы меняются за каждой дверью. Лёд, неон, тьма… Кто их пишет? В конце кто-то сидит на троне».", "Amelia's handwriting: \"The laws change behind every door. Ice, neon, darkness… Who writes them? Someone sits on a throne at the end.\"", "阿米莉亚的字迹：“每扇门后法则都会改变。冰、霓虹、黑暗……是谁写的？尽头有人坐在王座上。”", "Letra de Amelia: «Las leyes cambian tras cada puerta. Hielo, neón, oscuridad… ¿Quién las escribe? Al final alguien se sienta en un trono»." } },
            { "lore.work.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.work.photo.text", new[] { "Амелия и маленький Адам на летнем фестивале. Оба в лисьих масках и смеются.", "Amelia and little Adam at a summer festival. Both in fox masks, both laughing.", "阿米莉亚和小时候的亚当在夏日祭上。两人都戴着狐狸面具，笑得很开心。", "Amelia y el pequeño Adam en un festival de verano. Los dos con máscaras de zorro, riéndose." } },
            { "lore.work.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.work.calendar.text", new[] { "Обведён сегодняшний день: «Нашла на барахолке картридж без названия! Вечером проверю».", "Today's date circled: \"Found a cartridge with no name at the flea market! Will try it tonight.\"", "今天的日期被圈起来：“在跳蚤市场找到一张没有名字的卡带！今晚试试。”", "El día de hoy rodeado: «¡Encontré un cartucho sin nombre en el rastro! Lo pruebo esta noche»." } },
            { "lore.work.computer", new[] { "Консоль", "Console", "主机", "Consola" } },
            { "lore.work.computer.text", new[] { "На экране: «RULECRAWL. Новая игра. Игрок 1: АМЕЛИЯ». Курсор мигает на кнопке «Начать».", "On the screen: \"RULECRAWL. New game. Player 1: AMELIA.\" The cursor blinks on \"Start\".", "屏幕上：“RULECRAWL。新游戏。玩家1：阿米莉亚。”光标在“开始”上闪烁。", "En la pantalla: «RULECRAWL. Nueva partida. Jugador 1: AMELIA». El cursor parpadea sobre «Empezar»." } },
            { "lore.work.yuki", new[] { "Амелия", "Amelia", "阿米莉亚", "Amelia" } },
            { "lore.work.yuki.text", new[] { "«Адам? Ты тоже здесь?.. Нет, это просто сохранение. Слушай: не верь Системе. Я дошла до конца и увидела трон. Если встретишь Администратора — посмотри ему в глаза».", "\"Adam? You're here too?.. No, this is just a save. Listen: don't trust the System. I reached the end and saw the throne. If you meet the Administrator, look him in the eyes.\"", "“亚当？你也在这儿？……不，这只是个存档。听着：别相信系统。我走到了尽头，看到了王座。如果你见到管理员，看着他的眼睛。”", "«¿Adam? ¿Tú también estás aquí?.. No, esto solo es una partida guardada. Escucha: no te fíes del Sistema. Llegué al final y vi el trono. Si te encuentras con el Administrador, mírale a los ojos»." } },
            { "lore.dream.ren", new[] { "Адам", "Adam", "亚当", "Adam" } },
            { "lore.dream.ren.text", new[] { "«Сестра опять до утра играть собралась? Ладно… главное, чтобы в субботу пошла со мной на фестиваль».", "\"Sis is going to play till morning again? Fine… as long as she comes to the festival with me on Saturday.\"", "“姐姐又要玩通宵了？好吧……只要她星期六跟我去夏日祭就行。”", "«¿Otra vez va a jugar hasta el amanecer? Bueno… mientras venga conmigo al festival el sábado»." } },
            { "lore.dream.yuki", new[] { "Амелия", "Amelia", "阿米莉亚", "Amelia" } },
            { "lore.dream.yuki.text", new[] { "«Пройду эту игру — и дам тебе поиграть, Адам. Обещаю! Одна ночь — и всё».", "\"Once I beat this game I'll let you play, Adam. Promise! Just one night.\"", "“等我通关了就让你玩，亚当。我保证！就一个晚上。”", "«Cuando me pase este juego te dejo jugar, Adam. ¡Prometido! Solo una noche»." } },
            { "lore.dream.friends", new[] { "Алекс и Боб", "Alex and Bob", "亚历克斯和鲍勃", "Alex y Bob" } },
            { "lore.dream.friends.text", new[] { "«Амелия, ты с нами в субботу на фестиваль? — Если пройду игру за ночь! — Она всегда так говорит, Адам. Тащи её за руку».", "\"Amelia, coming to the festival with us on Saturday? — If I beat the game tonight! — She always says that, Adam. Drag her by the hand.\"", "“阿米莉亚，星期六跟我们去夏日祭吗？——要是今晚能通关的话！——她总这么说，亚当。拉着她的手走就是了。”", "«Amelia, ¿vienes al festival con nosotros el sábado? —¡Si me paso el juego esta noche! —Siempre dice lo mismo, Adam. Llévala de la mano»." } },
            { "lore.silence.ren", new[] { "Адам", "Adam", "亚当", "Adam" } },
            { "lore.silence.ren.text", new[] { "«Все говорят, что Амелия сбежала. Но она бы не пропустила фестиваль со мной. Если консоль её забрала — пусть заберёт и меня».", "\"Everyone says Amelia ran away. But she'd never have skipped the festival with me. If the console took her, let it take me too.\"", "“大家都说阿米莉亚离家出走了。可她绝不会丢下我不去夏日祭。如果是主机带走了她——那就把我也带走吧。”", "«Todos dicen que Amelia se escapó. Pero nunca se habría perdido el festival conmigo. Si la consola se la llevó, que me lleve a mí también»." } },
            { "codex.saveFiles", new[] { "Сохранения Амелии: {0}/{1}", "Amelia's saves: {0}/{1}", "阿米莉亚的存档：{0}/{1}", "Partidas de Amelia: {0}/{1}" } },
            { "codex.finales", new[] { "Концовки: {0}/{1}", "Endings: {0}/{1}", "结局：{0}/{1}", "Finales: {0}/{1}" } },
        };
    }
}
